    session_file = os.path.normpath(os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl'))

    try:
        with open(session_file, 'r') as f:
            content = f.read()
    except Exception as e:
        print(f"Could not read session file: {e}")
        return {}

    G = {}

    # Better parsing
    current_key = None

    for line_num, line in enumerate(lines := content.split('\n')):
        if 'Demo pair' in line:
            match = re.match(r'(Demo pair \d+) (input|output) \((\d+)x(\d+)\):', line)
            if match:
                name = match.group(1)
                parts = match.group(2), match.group(3), match.group(4)
                key = (name, parts[2], parts[3], parts[0])
                G[key] = []
        elif current_key and line.strip():
            # Parse grid row
            rows = []
            for row_line in line.split('\n'):
                row_line = row_line.strip()
                if row_line:
                    rows.append([int(x) for x in row_line.split()])
            G[current_key].extend(rows)

    # Convert to proper grid format by combining rows
    result = {}
    for key, rows in G.items():
        grid = []
        row_size = None
        for row_batch in rows:
            for row in row_batch:
                if row_size is None:
                    row_size = len(row)
                grid.append(row)
        result[key] = grid

    return result

